import {renderJourney,currentProfile} from './journey.js';
import {assessJob} from './matching.js';
import {ROLE_FAMILIES,DEGREES,freshFilters,unique,filteredJobs,aggregate,counts,salaryText,locationText,degreeText,pathwayMatch,toCSV,filtersFromSearch,filtersToSearch} from './core.js';
const $=s=>document.querySelector(s);
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=u=>{try{const x=new URL(u,location.href);return ['https:','http:'].includes(x.protocol)?e(x.href):'#';}catch{return '#';}};
const date=v=>v?new Date(v).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}):'Not stated';
const pct=(n,d)=>d?Math.round(n/d*100):0;
function readStored(key){try{const x=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(x)?x.filter(i=>typeof i==='string'):[];}catch{return [];}}
const state={jobs:[],meta:{},coverage:[],filters:filtersFromSearch(location.search),view:['guide','explore','insights','compare','methodology'].includes(location.hash.slice(1))?location.hash.slice(1):'guide',saved:readStored('compass-saved'),compare:[],page:1,pageSize:10};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
function filtered(){return filteredJobs(state.jobs,state.filters,state.saved);}
function options(values,current,all='All'){return `<option value="">${e(all)}</option>`+values.map(v=>`<option value="${e(v)}" ${String(v)===String(current)?'selected':''}>${e(v)}</option>`).join('');}
function select(key,label,values,all,help=''){return `<div class="filter-group"><label class="filter-label" for="filter-${key}">${label}</label><select id="filter-${key}" data-filter="${key}">${options(values,state.filters[key],all)}</select>${help?`<p class="filter-help">${help}</p>`:''}</div>`;}
function checks(key,label,values){return `<fieldset class="filter-group" style="border:0;padding:0"><legend class="filter-label">${label}</legend>${values.map(v=>`<label class="check-row"><input type="checkbox" data-array="${key}" value="${e(v)}" ${state.filters[key].includes(v)?'checked':''}>${e(v==='Bachelor'?"Bachelor’s":v==='Master'?"Master’s":v)}</label>`).join('')}</fieldset>`;}
function check(key,label,help=''){return `<label class="check-row"><input type="checkbox" data-boolean="${key}" ${state.filters[key]?'checked':''}>${label}</label>${help?`<p class="filter-help">${help}</p>`:''}`;}
function renderFilters(){const f=state.filters,j=state.jobs;const years=unique(j.flatMap(x=>x.qualificationPaths.flatMap(p=>p.graduationYears||[]))).sort();
 const advancedOpen=$('details.advanced')?.open;
 $('#filter-fields').innerHTML=checks('degrees','Degree pathway',DEGREES)+select('state','US location',unique(j.flatMap(x=>x.locations.map(l=>l.state))).sort().concat(j.some(x=>x.remote)?['Remote']:[]),'Anywhere in the US')+select('city','City',unique(j.flatMap(x=>x.locations.map(l=>l.city))).sort(),'All cities')+checks('roles','Role family',ROLE_FAMILIES)+select('graduation','Graduation year',years,'Any / not specified','A year filter is approximate. Check the exact months in each posting.')+select('start','Start year',unique(j.flatMap(x=>x.startYears)).sort(),'Any start year')+`<hr class="filter-divider">`+check('includeZero','Include zero-experience pathways')+check('includeEarly','Include 0–2 year pathways','Some experience may be required; read the degree-specific pathway.')+check('includeUnclear','Investigate unclear eligibility','Live AI roles without a clear graduate pathway. Not verified as new-grad eligible.')+check('includeUnknown','Keep unspecified requirements','Missing degree, experience, start-date, pay or work-mode fields remain visible.')+`<details class="advanced" ${advancedOpen?'open':''}><summary>More filters</summary>`+select('company','Company',unique(j.map(x=>x.company)).sort(),'All companies')+select('workplace','Work arrangement',['On-site','Hybrid','Remote'],'Any arrangement')+`<div class="filter-group"><label class="filter-label" for="filter-experience">Full-time industry experience</label><select id="filter-experience" data-filter="experience"><option value="">Any requirement</option>${['0','1','2'].map(v=>`<option value="${v}" ${f.experience===v?'selected':''}>${v} years available</option>`).join('')}</select><p class="filter-help">Research and coursework requirements still apply.</p></div>`+select('skill','Skill mentioned',unique(j.flatMap(x=>x.skills.map(s=>s.name))).sort(),'Any skill')+select('tag','Technical focus',unique(j.flatMap(x=>x.tags)).sort(),'Any focus')+select('sponsorship','Sponsorship statement',['Supported','Not offered','Conditional','Not stated'],'Any statement','Only explicit employer statements. “Not stated” means unknown.')+`<div class="filter-group"><label class="filter-label" for="filter-salary">Salary upper bound</label><select id="filter-salary" data-filter="salary"><option value="">Any disclosed range</option>${[100000,150000,200000].map(v=>`<option value="${v}" ${f.salary===String(v)?'selected':''}>At least $${v/1000}k / year</option>`).join('')}</select><p class="filter-help">USD annual base ranges only. An upper bound is not an offered salary.</p></div>`+`<div class="filter-group">${check('deadlineOnly','Has a stated application deadline')}</div></details>`;
 $('#search').value=f.q;
}
function stat(label,value,note,accent=false,icon=''){return `<div class="stat ${accent?'accent':''}"><div class="stat-label">${label}</div>${icon?`<span class="stat-icon" aria-hidden="true">${icon}</span>`:''}<div class="stat-number">${value}</div><div class="stat-note">${note}</div></div>`;}
function renderSummary(jobs){const a=aggregate(jobs);$('#summary').innerHTML=stat('Opportunities',a.total,'Unique postings in this view',false,'↗')+stat('Companies',a.companies,'Public employer listings',false,'▦')+stat('US states & DC',a.states,'From stated work locations',false,'◎')+stat('Explicit new grad',a.explicit,`${a.total-a.explicit} other pathways / unclear eligibility`,true,'✳');}
const statusLabel=s=>({'explicit':'Explicit new grad','zero-experience':'Zero-experience pathway','early-career':'0–2 year pathway','unclear':'Graduate eligibility unclear'}[s]||'Eligibility unclear');
const labels={q:'Search',degrees:'Degree',roles:'Role',state:'Location',city:'City',company:'Company',workplace:'Work mode',graduation:'Graduation',start:'Start',experience:'Industry years',skill:'Skill',tag:'Focus',sponsorship:'Sponsorship',salary:'Pay ceiling',deadlineOnly:'Has deadline',includeZero:'Zero-experience roles',includeEarly:'0–2 year pathways',includeUnclear:'Unclear eligibility',includeUnknown:'Known requirements only',savedOnly:'Saved only'};
function renderChips(){const f=state.filters;$('#active-filters').innerHTML=Object.entries(f).flatMap(([k,v])=>{if(k==='sort')return [];if(k==='includeUnknown')return v?[]:[`<button class="filter-chip" data-clear="${k}">${labels[k]} ×</button>`];if(!v||Array.isArray(v)&&!v.length)return [];return (Array.isArray(v)?v:[v]).map(x=>`<button class="filter-chip" data-clear="${k}" data-value="${e(x)}">${e(labels[k])}${typeof x==='boolean'?'':`: ${e(x)}`} ×</button>`);}).join('');}
function avatar(j){let hash=0;for(const c of j.company)hash+=c.charCodeAt(0);return `<span class="company-avatar avatar-${hash%5}" aria-hidden="true">${e(j.company.replace(/[^a-zA-Z0-9 ]/g,'').split(' ').map(w=>w[0]).join('').slice(0,2))}</span>`;}
function saveButton(j){return `<button class="save-button ${state.saved.includes(j.id)?'saved':''}" data-save="${e(j.id)}" aria-label="${state.saved.includes(j.id)?'Unsave':'Save'} ${e(j.company+' '+j.title)}" aria-pressed="${state.saved.includes(j.id)}">${state.saved.includes(j.id)?'▣':'▢'}</button>`;}
function card(j){const qm=pathwayMatch(j,state.filters);const unknownTag=qm==='unknown'?'<span class="tag amber">Some requirements unspecified</span>':'';return `<article class="job-card"><div class="card-top">${avatar(j)}<div class="card-main"><div class="company-line">${e(j.company)}</div><h3><button class="card-title" data-detail="${e(j.id)}">${e(j.title)}</button></h3><div class="job-meta"><span>⌾ ${e(locationText(j))}</span><span>${e(j.workplace)}</span><span>${e(salaryText(j))}</span></div></div>${saveButton(j)}</div><div class="tags"><span class="tag ${j.newgradStatus==='unclear'?'amber':'green'}">${statusLabel(j.newgradStatus)}</span>${j.reviewLevel==='automated-discovery'?'<span class="tag amber">Automated discovery</span>':''}<span class="tag blue">${e(j.roleFamily)}</span>${j.tags.slice(0,2).map(t=>`<span class="tag">${e(t)}</span>`).join('')}${unknownTag}</div><p class="qualification-line"><strong>${e(degreeText(j))}</strong> <span aria-hidden="true">·</span> ${e(j.qualificationNote||j.qualificationPaths.map(p=>p.evidence).join(' OR '))}</p><div class="card-bottom"><span class="card-verified">Checked ${e(date(j.verifiedAt))} · ${e(j.source)}</span><div class="card-actions"><label class="compare-checkbox"><input type="checkbox" data-compare="${e(j.id)}" ${state.compare.includes(j.id)?'checked':''}>Compare</label><button class="details-link" data-detail="${e(j.id)}">View evidence ↗</button></div></div></article>`;}
function empty(title,message,action='Reset filters'){return `<div class="empty-state"><span class="empty-symbol" aria-hidden="true">⌕</span><h3>${title}</h3><p>${message}</p><button class="button" data-action="${action==='Explore jobs'?'explore':'reset'}">${action}</button></div>`;}
function renderExplore(jobs){const pages=Math.max(1,Math.ceil(jobs.length/state.pageSize));state.page=Math.min(state.page,pages);const shown=jobs.slice((state.page-1)*state.pageSize,state.page*state.pageSize);return `<div class="results-options"><div class="view-toggles"><span>Public technical roles</span><button class="saved-toggle ${state.filters.savedOnly?'active':''}" data-action="saved">Saved (${state.saved.length})</button></div><label>Sort <select id="sort" aria-label="Sort jobs">${[['company','Company A–Z'],['title','Role title A–Z'],['published','Source publish date'],['deadline','Stated deadline'],['salary','Salary upper bound']].map(([k,v])=>`<option value="${k}" ${state.filters.sort===k?'selected':''}>${v}</option>`).join('')}</select></label></div>${jobs.length?`<div class="job-list">${shown.map(card).join('')}</div><div class="pagination"><button class="button" data-page="${state.page-1}" ${state.page===1?'disabled':''}>← Previous</button><span>${state.page} / ${pages}</span><button class="button" data-page="${state.page+1}" ${state.page===pages?'disabled':''}>Next →</button></div>`:empty('No roles match these filters.','Try removing a location or degree condition. Unknown requirements are handled by the option in the filters.')}<p class="sample-note">Curated graduate postings and separately labeled automated discovery leads, checked on the date shown. Counts describe postings, not hiring headcount or the full US market.</p>`;}
function bars(rows,type,color='blue',limit=8){if(!rows.length)return '<p class="muted">No observations in this view.</p>';const max=Math.max(...rows.map(r=>r.count));return rows.slice(0,limit).map(r=>`<div class="bar-row"><button class="bar-label" data-chart="${type}" data-value="${e(r.label)}" title="${r.count} postings across ${r.companies} companies. Filter this group.">${e(r.label)}</button><div class="bar-track" aria-hidden="true"><div class="bar-fill ${color}" style="width:${r.count/max*100}%"></div></div><span class="bar-count">${r.count}</span></div>`).join('');}
function panel(title,sub,content,note='',full=false){return `<section class="panel ${full?'full':''}"><div class="panel-header"><div><h3>${title}</h3><p>${sub}</p></div><span class="chart-unit">Postings</span></div>${content}${note?`<p class="chart-note">${note}</p>`:''}</section>`;}
function findings(){const jobs=state.jobs.filter(j=>j.newgradStatus==='explicit'),a=aggregate(jobs);if(!jobs.length)return '';const outside=jobs.filter(j=>j.locations.some(l=>l.state&&l.state!=='CA')||j.remote),outsideCompanies=unique(outside.map(j=>j.company)).length;const multi=jobs.filter(j=>unique(j.qualificationPaths.flatMap(p=>p.degrees)).length>1).length;const ms=jobs.filter(j=>j.qualificationPaths.some(p=>p.degrees.includes('Master')&&(p.minYears===0||p.minYears===null)));const topRole=counts(ms,j=>[j.roleFamily])[0];const topSkill=counts(jobs,j=>j.skills.filter(s=>s.level==='required').map(s=>s.name))[0];return `<section class="panel full"><div class="panel-header"><div><h3>What this snapshot suggests</h3><p>Findings from the full explicit-new-grad sample: ${a.total} postings, ${a.companies} companies. These findings do not change with the filters.</p></div></div><div class="insight-callout"><h4>1. Expand your search beyond California.</h4><p>${outside.length} of ${a.total} postings (${pct(outside.length,a.total)}%) list a US location outside California or remote work (restrictions may apply), across ${outsideCompanies} companies. If location is flexible, check those opportunities alongside California roles. This does not estimate regional hiring odds.</p><button class="inline-link" data-action="all-insights">See the full geographic breakdown</button></div>${topRole?`<div class="insight-callout"><h4>2. Search by degree pathway and role family.</h4><p>Among ${ms.length} postings with a listed Master’s pathway and no positive industry minimum recorded, ${topRole.count} are in ${e(topRole.label)}, across ${topRole.companies} companies. Use that category as one starting point, then read each pathway’s experience and graduation conditions. Missing experience values still need confirmation.</p><button class="inline-link" data-recommend-role="${e(topRole.label)}">Explore this category with a Master’s filter</button></div>`:''}${topSkill?`<div class="insight-callout"><h4>3. Make relevant technical evidence easy to find.</h4><p>${e(topSkill.label)} appears in required-skill text for ${topSkill.count}/${a.total} postings, across ${topSkill.companies} companies. For roles that request it, make a relevant project easy to find in your application. A keyword mention alone does not establish proficiency or predict selection.</p></div>`:''}<p class="chart-note">${multi} postings list more than one degree option. ${a.salaryDisclosed}/${a.total} disclose an annual USD base range. Suggestions are exploratory and apply to the collected sample.</p></section>`;}
function renderInsights(jobs){if(!jobs.length)return empty('No observations to chart.','Adjust the filters to explore the collected sample.');const a=aggregate(jobs);const degreeRows=DEGREES.map(d=>({label:d,count:jobs.filter(j=>j.qualificationPaths.some(p=>p.degrees.includes(d))).length,companies:unique(jobs.filter(j=>j.qualificationPaths.some(p=>p.degrees.includes(d))).map(j=>j.company)).length}));const topSkills=a.skills.slice(0,8),families=ROLE_FAMILIES.filter(r=>jobs.some(j=>j.roleFamily===r));const table=`<div class="table-scroll"><table class="data-table heatmap"><caption class="skip-link">Skill mentions by primary role family</caption><thead><tr><th scope="col">Skill</th>${families.map(r=>`<th scope="col">${e(r)}<br>n=${jobs.filter(j=>j.roleFamily===r).length}</th>`).join('')}</tr></thead><tbody>${topSkills.map(s=>`<tr><th scope="row">${e(s.label)}</th>${families.map(r=>{const group=jobs.filter(j=>j.roleFamily===r);const n=group.filter(j=>j.skills.some(sk=>sk.name===s.label)).length;return `<td style="background:rgba(40,93,215,${n/group.length*.18})" title="${n}/${group.length} postings mention ${e(s.label)}">${n}/${group.length}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;return `<p class="sample-note">Current filters: ${a.total} unique postings across ${a.companies} companies. Click a chart label to inspect the underlying roles.</p><div class="chart-grid">${panel('Where opportunities are listed','Stated US work locations',bars(a.locations,'state'),'Multi-location postings appear in each stated state. Counts overlap. US remote is a separate group.')}${panel('Which AI roles are represented','One primary role family per posting',bars(a.roles,'roles','lime'),'Categories describe the main responsibility. Skills and technical focus can overlap.')}${panel('Degree pathways','Postings that name each degree',bars(degreeRows,'degrees'),`A posting can name multiple degrees with different experience requirements. ${jobs.filter(j=>!j.qualificationPaths.some(p=>p.degrees.length)).length} postings have no established degree path. These bars overlap. A named degree does not guarantee eligibility.`)}${panel('Skills in the sample','Most frequently mentioned technical skills',bars(a.skills,'skill','lime'),'Mentions include required, preferred and contextual skills. See each posting for alternatives and required/preferred distinctions.')}${panel('Skill patterns by role family','Count mentioning a skill / postings in that family',table,'Small samples and repeated employer templates can affect patterns. Multiple mentions within one posting count once.',true)}${findings()}</div>`;}
function comparisonRow(title,html){return `<div class="comparison-row"><h4>${title}</h4>${html}</div>`;}
function renderCompare(){const jobs=state.compare.map(id=>state.jobs.find(j=>j.id===id)).filter(Boolean);const saved=state.jobs.filter(j=>state.saved.includes(j.id));return `${jobs.length?`<div class="compare-grid" style="--cols:${jobs.length}">${jobs.map(j=>`<article class="compare-card"><button class="text-button remove" data-compare-remove="${e(j.id)}" aria-label="Remove ${e(j.company+' '+j.title)} from comparison">Remove ×</button>${avatar(j)}<p class="muted" style="margin-top:10px">${e(j.company)}</p><h3>${e(j.title)}</h3><button class="inline-link" data-detail="${e(j.id)}">View source evidence ↗</button>${comparisonRow('Role',e(j.summary))}${comparisonRow('Location & arrangement',`${e(locationText(j))}<br>${e(j.workplace)}`)}${comparisonRow('Qualification pathways',j.qualificationPaths.map(p=>`<p><strong>${e(p.degrees.join(' / ')||'Not stated')}</strong><br>${e(p.evidence)}</p>`).join('<br>'))}${comparisonRow('Graduation / start',`${e(unique(j.qualificationPaths.map(p=>p.graduation)).join('; '))}<br>Start: ${e(j.startWindow)}`)}${comparisonRow('Skills',j.skills.map(s=>`${e(s.name)} <span class="muted">(${e(s.level)})</span>`).join(', '))}${comparisonRow('Base salary',j.salary.length?j.salary.map(s=>`${e(s.currency)} ${Number(s.min).toLocaleString()}–${Number(s.max).toLocaleString()} / ${e(s.period)}<br><span class="muted">${e(s.scope)}</span>`).join('<br>'):'Not stated')}${comparisonRow('Sponsorship statement',`${e(j.sponsorship)}<br><span class="muted">${e(j.sponsorshipNote)}</span>`)}${comparisonRow('Deadline / verification',`${e(date(j.deadline))}<br>Checked ${e(date(j.verifiedAt))}`)}<a class="button primary" href="${safeUrl(j.url)}" target="_blank" rel="noopener noreferrer">Official posting ↗</a></article>`).join('')}</div>`:empty('A clearer view, side by side.','Select Compare on up to three job cards. Their qualification pathways and disclosed terms will appear here.','Explore jobs')}<section class="saved-section"><h3>Saved on this device <span class="muted">(${saved.length})</span></h3>${saved.length?`<div class="job-list">${saved.map(card).join('')}</div>`:'<p class="muted">Use the bookmark on a job card to save it here. No account or personal data required.</p>'}</section>`;}
function downloadLink(href,title,sub,kind='CSV'){return `<a class="document-link" href="${href}" ${kind==='HTML'?'target="_blank" rel="noopener"':'download'}><span>${title}<small>${sub}</small></span><span class="file-icon">${kind} ↓</span></a>`;}
function renderMethodology(){const a=aggregate(state.jobs),coverage=state.coverage;return `<div class="artifact-banner"><div><h3>A five-minute tour of the evidence</h3><p>A presentation and live-demo guide for this project.</p></div><a class="button" href="./presentation.html" target="_blank" rel="noopener">Open presentation ↗</a></div><div class="chart-grid"><section class="panel full"><h3>Download the research</h3><p class="muted" style="margin-top:8px">Full snapshot: ${a.total} postings, ${a.companies} employers. CSV tables share a stable job ID.</p><div class="document-links">${downloadLink('./downloads/jobs.csv','Job dataset','One row per unique posting')}${downloadLink('./downloads/qualification_paths.csv','Qualification pathways','Degree, experience and graduation conditions')}${downloadLink('./downloads/job_locations.csv','Job locations','One row per stated work location')}${downloadLink('./downloads/job_skills.csv','Skill evidence','Required, preferred or mentioned')}${downloadLink('./downloads/salary_ranges.csv','Salary ranges','Currency, period and location scope')}${downloadLink('./downloads/source_coverage.csv','Source coverage','Checked sources and access limitations')}${downloadLink('./downloads/methodology.pdf','One-page methodology','Collection, definitions and limitations','PDF')}${downloadLink('./downloads/reflection.pdf','Project reflection','What the evidence can and cannot support','PDF')}${downloadLink('./downloads/demo-script.md','Five-minute demo script','Speaking notes and live-demo sequence','MD')}${downloadLink('./downloads/data-dictionary.md','Data dictionary','Field definitions and units','MD')}</div>${state.meta.githubUrl?`<a class="button" href="${safeUrl(state.meta.githubUrl)}" target="_blank" rel="noopener">Source code on GitHub ↗</a>`:`<a class="button" href="./downloads/source-code.zip" download>Download source code ↓</a>`}</section><section class="panel full method-prose"><h3 style="margin-top:0">Purpose and intended users</h3><p>AI Career Compass helps students who are new to AI job searching understand role types, explore options using their background and preferences, and decide what to investigate or prepare next. Career centers can use it as an evidence-based discussion aid.</p><h3>How the data was collected</h3><p>We selected employers across AI products, infrastructure, large technology companies and applied ML. We read public employer career pages and official ATS listings, including Greenhouse, Ashby, Lever and company-hosted pages. Public job lists, search engines, and an earlier personal search dataset served only as discovery aids. That earlier collection targeted Bay Area LLM roles; its personal rankings, applicant details and application notes were not imported. Additional employer boards and nationwide searches broaden the sample, while source selection bias remains. Each included posting links to its official source.</p><p>Collection and source checks took place on ${e(state.meta.snapshotDate||'the date shown above')}. This is a purposive, time-stamped sample, not a census of US hiring. The source log distinguishes no qualifying roles from inaccessible pages. ${coverage.length} source entries were checked.</p><h3>Inclusion rules</h3><ol><li><strong>United States:</strong> a specific US work location or explicit US remote eligibility. Generic “remote” alone is insufficient.</li><li><strong>AI work:</strong> model research, training, evaluation, deployment, AI applications or infrastructure supporting ML. Company branding and generic use of AI tools do not qualify a role.</li><li><strong>New graduate:</strong> explicit graduate language in the employer’s title, program or description. Other groups are explicitly labeled: zero-experience pathways; early-career pathways requiring up to two years; and exploratory roles with unclear graduate eligibility. An omitted experience requirement is unknown, not zero. Broader groups are individually selectable and never presented as confirmed new-grad eligibility.</li><li><strong>Role-specific posting:</strong> an official career or ATS source with a job URL. Curated roles target full-time opportunities; Ashby discovery additionally checks its FullTime field. Greenhouse discovery does not independently establish employment terms. Internships, co-ops, senior titles, postdocs and generic talent pools are screened out.</li></ol><h3>Qualification and date definitions</h3><p>Degree and experience requirements stay together as alternative pathways. A Master’s path cannot be used to infer Bachelor’s eligibility. Coursework and research experience remain distinct from full-time industry experience. “2027 Start” is a start date, not automatically a graduation date. A year filter is a broad aid; exact graduation months remain visible in the evidence.</p><p>“Not stated” means a value is missing or not established in our record. Automated discovery does not extract every field; missing values do not prove the employer omitted them. Unless switched off, unspecified values remain visible when filtering eligibility, start dates, pay and work arrangement. Sponsorship filters use explicit statements only. None of these filters certifies eligibility.</p><h3>Personalization and scenario rules</h3><p>Personalization uses transparent rules, not a trained prediction model. Degree, graduation year, industry experience and research experience are checked within the same alternative pathway. Known conflicts, unresolved requirements, and alignment of recorded basics remain separate. Interests, preferred work states, work arrangement and disclosed salary influence ordering within those groups. A selected skill means self-reported project exposure, not professional proficiency. A required-skill gap prompts confirmation; it is not an automated rejection.</p><p>The skill experiment counts posting–skill connections within chosen interests and without a recorded basic conflict. Each selected skill mentioned in a posting contributes one connection; a posting may contribute several. This is keyword overlap, not eligibility gained by learning a tool. The location experiment changes preference coverage without changing qualification rules. No acceptance probabilities, personality types, or hidden fit percentages are generated.</p><h3>Units, deduplication and analysis</h3><p>The main unit is a unique posting, deduplicated by employer and official job/requisition ID or canonical URL. One posting may recruit multiple people. Multiple US locations remain attached to one job. State and degree counts can overlap. Each job has one primary role family, so role-family counts add to the posting total.</p><p>Skills count once per posting regardless of repetitions. Salary data describe advertised base ranges with their original currency, period and location scope. They are not actual pay, total compensation or expected offers. Published, updated and verified timestamps are different fields. All charts use the current filtered posting set; full-snapshot recommendations are labeled separately.</p><h3>Verification and AI assistance</h3><p>AI agents assisted discovery, structured extraction and website implementation. Curated records received source review for US location, AI responsibilities and graduate pathways. The separately labeled automated-discovery layer screens whole public boards for AI titles, US locations and recognizable experience references. It rejects recognized 3+ year requirements, including preferred ones, but cannot reliably parse every alternative. All discovery leads keep graduate eligibility unclear, degree and experience pathways unknown, and unreviewed pay and sponsorship blank. Their presence in an official board is not confirmation of an active application form or graduate eligibility. Structured validation checks identifiers, allowed categories, evidence fields and consistency. The project does not claim employer or third-party certification. Ambiguous records were excluded or annotated.</p><h3>Missing data, bias and uncertainty</h3><p>ATS access, employer selection, uneven disclosure and search indexing affect which jobs appear. Large employers with many graduate postings can dominate counts. A source that could not be accessed is not evidence of no hiring. A blank state on a map or chart means no observation in this sample. Small groups should not drive broad rankings.</p><p>These data support comparisons of stated requirements and search strategies within the sample. They cannot estimate hiring headcount, applicant competition, acceptance probability, visa outcomes, causal salary returns or growth over time. Job availability may change after verification. Recheck the official posting before applying.</p><h3>Privacy</h3><p>The dataset contains public job facts and short source evidence. It contains no applicant names, contact details, resumes or personal locations. Saved jobs stay in your browser. Profile answers remain in memory unless you opt to remember them on this device; they are never sent to a server or placed in shared URLs. You can clear the profile. Optional plan downloads include only the background and preferences you selected. The site sends you to the employer to apply.</p><h3>Collection sources</h3><p><a href="https://docs.greenhouse.io/job-board.html" target="_blank" rel="noopener">Greenhouse Job Board API</a> · <a href="https://github.com/lever/postings-api" target="_blank" rel="noopener">Lever Postings API</a> · <a href="https://developers.ashbyhq.com/docs/public-job-posting-api" target="_blank" rel="noopener">Ashby public API documentation</a>. Access failures are recorded without assuming the employer is not hiring. Employer-specific sources appear below and on each role.</p></section><section class="panel full"><div class="panel-header"><div><h3>Source coverage log</h3><p>Observed access and screening results, including unsuccessful checks. A discovery lead is not a verified graduate opening.</p></div></div><div class="coverage-table"><table class="data-table"><thead><tr><th>Employer</th><th>Result</th><th>Note</th></tr></thead><tbody>${coverage.map(c=>`<tr><td><a href="${safeUrl(c.url)}" target="_blank" rel="noopener">${e(c.company)}</a></td><td>${e(c.note?.startsWith('Automated')?(c.qualifyingCount?'Discovery leads':'No leads passed screen'):c.status)}</td><td>${e(c.note)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel full method-prose"><h3 style="margin-top:0">Reflection</h3><p>The most important design choice was to make the qualification evidence visible. A graduate label can coexist with degree-specific experience requirements. Flattening those requirements would create a reassuring but misleading filter.</p><p>The snapshot supports a useful shortlist and a comparison of stated opportunities. It cannot show the whole labor market or tell a student how likely they are to receive an offer. Collecting a larger number of weakly classified postings would not remove that limitation.</p><p>A stronger follow-up would expand the employer sampling frame, independently double-code a subset of records and retain repeated snapshots. That would make coverage and annotation agreement measurable and permit a carefully defined analysis of changes over time.</p></section></div>`;}
function render(){document.body.classList.toggle('guide-mode',state.view==='guide');const jobs=filtered();renderSummary(jobs);renderChips();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#compare-count').textContent=state.compare.length;
 const names={guide:['YOUR PERSONAL COMPASS','Find your starting point',''],explore:['EXPLORE OPPORTUNITIES',`${jobs.length} ${jobs.length===1?'opportunity':'opportunities'}`,`${unique(jobs.map(j=>j.company)).length} companies · ${state.filters.includeUnclear?'Including unclear graduate eligibility':state.filters.includeEarly?'Including 0–2 year pathways':state.filters.includeZero?'Graduate + zero-experience pathways':'Explicit new-grad postings'}`],insights:['UNDERSTAND THE SAMPLE','A view of your opportunities',`${jobs.length} filtered postings · Figures describe this sample`],compare:['MAKE AN INFORMED CHOICE','Compare your options','Keep the requirements and source evidence side by side.'],methodology:['FOLLOW THE EVIDENCE','Data & methodology','Sources, definitions, downloads and project materials.']};
 const [eyebrow,title,subtitle]=names[state.view];$('#view-eyebrow').textContent=eyebrow;$('#results-title').textContent=title;$('#result-subtitle').textContent=subtitle;
 if(state.view==='guide')renderJourney($('#view-content'),{jobs:state.jobs,meta:state.meta,saved:state.saved,compare:state.compare,toast});else $('#view-content').innerHTML=state.view==='explore'?renderExplore(jobs):state.view==='insights'?renderInsights(jobs):state.view==='compare'?renderCompare():renderMethodology();
 $('#compare-tray').hidden=!state.compare.length||state.view==='compare';$('#compare-tray').innerHTML=`<strong>${state.compare.length} / 3 roles selected</strong><button class="button" data-view="compare">Compare roles ↗</button><button class="text-button" data-action="clear-compare">Clear</button>`;
 const search=filtersToSearch(state.filters);history.replaceState(null,'',`${location.pathname}${search?'?'+search:''}#${state.view}`);
}
function setView(view){if(!['guide','explore','insights','compare','methodology'].includes(view))return;state.view=view;render();$('#filters').classList.remove('open');}
function setFilter(key,value){state.filters[key]=value;state.page=1;renderFilters();render();}
function reset(){state.filters=freshFilters();state.page=1;renderFilters();render();}
function toggleSave(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];try{localStorage.setItem('compass-saved',JSON.stringify(state.saved));}catch{toast('Your browser could not save preferences.');}render();if($('#job-dialog').open)openDetail(id,false);}
function toggleCompare(id){if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<3)state.compare.push(id);else toast('Compare up to three roles. Remove one to add another.');render();}
function openDetail(id,show=true){const j=state.jobs.find(x=>x.id===id);if(!j)return;const personal=currentProfile();const personalAssessment=personal?assessJob(j,personal):null;const m=pathwayMatch(j,state.filters);const status=m==='match'?'The displayed degree, graduation and industry-experience conditions match the filters. Check all remaining requirements at the source.':m==='unknown'?'Some selected requirements are not stated clearly. Confirm them with the employer before relying on this match.':m==='conflict'?'This role conflicts with one or more current qualification filters. Read its pathways below.':'Choose degree or graduation filters to inspect the stated qualification pathways.';
 $('#job-detail').innerHTML=`<div class="detail-head"><span>ROLE DETAILS / SOURCE EVIDENCE</span><button class="icon-button" data-action="close-detail" aria-label="Close role details">×</button></div><div class="detail-body"><div class="card-top">${avatar(j)}<div class="card-main"><p class="muted">${e(j.company)}</p></div>${saveButton(j)}</div><h2 id="dialog-title">${e(j.title)}</h2><p class="muted">${e(locationText(j))} · ${e(j.workplace)}</p><div class="tags"><span class="tag ${j.newgradStatus==='unclear'?'amber':'green'}">${statusLabel(j.newgradStatus)}</span>${j.reviewLevel==='automated-discovery'?'<span class="tag amber">Automated discovery</span>':''}<span class="tag blue">${e(j.roleFamily)}</span>${j.tags.map(t=>`<span class="tag">${e(t)}</span>`).join('')}</div><p class="detail-summary">${e(j.summary)}</p>${personalAssessment?`<section class="personal-detail-note"><strong>Your profile: ${e({aligned:"Stated basics align",confirm:"Check requirements",gap:"A stated condition differs"}[personalAssessment.status])}</strong>${[...personalAssessment.matched,...personalAssessment.gaps,...personalAssessment.unknown].map(x=>`<p>${e(x)}</p>`).join("")}<small>Profile preferences and project exposure are an exploration aid, not proof of eligibility.</small></section>`:""}<div class="qualification-state">${e(status)}</div><section class="detail-section"><h3>Why this role is included</h3><div class="evidence-item"><small>Graduate pathway · source-based summary</small><p>${e(j.newgradEvidence)}</p></div><div class="evidence-item"><small>AI responsibilities · source-based summary</small><p>${e(j.aiEvidence)}</p></div><p class="detail-note">Evidence summaries paraphrase the employer’s posting. <a href="${safeUrl(j.url)}" target="_blank" rel="noopener">Read the original ↗</a></p></section><section class="detail-section"><h3>Qualification pathways</h3>${j.qualificationPaths.map((p,i)=>`<div class="evidence-item"><small>Pathway ${i+1} · ${e(p.degrees.join(' / ')||'Degree not stated')}</small><p>${e(p.evidence)}</p><p class="detail-note">Graduation: ${e(p.graduation)}${p.minYears===null?' · Industry experience: not stated':` · Minimum experience recorded: ${p.minYears} years (${e(p.experienceType)})`}</p></div>`).join('')}<p class="detail-note">${e(j.qualificationNote)}</p></section><section class="detail-section"><h3>Technical requirements</h3>${['required','preferred','mentioned'].map(level=>{const skills=j.skills.filter(s=>s.level===level);return skills.length?`<p class="detail-note"><strong>${level[0].toUpperCase()+level.slice(1)}</strong></p><div class="tags">${skills.map(s=>`<span class="tag">${e(s.name)}${s.alternativeGroup?' (alternative)':''}</span>`).join('')}</div>`:'';}).join('')}<p class="detail-note">Alternative skills may satisfy the same requirement. Refer to the original wording for “or” conditions.</p></section><section class="detail-section"><h3>Disclosed terms</h3><dl class="detail-facts"><div><dt>Base salary</dt><dd>${j.salary.length?j.salary.map(s=>`${e(s.currency)} ${Number(s.min).toLocaleString()}–${Number(s.max).toLocaleString()} / ${e(s.period)}<br>${e(s.scope)}`).join('<br><br>'):'Not stated'}</dd></div><div><dt>Start window</dt><dd>${e(j.startWindow)}</dd></div><div><dt>Sponsorship statement</dt><dd>${e(j.sponsorship)}<br>${e(j.sponsorshipNote)}</dd></div><div><dt>Application deadline</dt><dd>${e(date(j.deadline))}</dd></div><div><dt>Source publication date</dt><dd>${e(date(j.publishedAt))}</dd></div><div><dt>Last checked</dt><dd>${e(date(j.verifiedAt))}</dd></div></dl></section><p class="detail-note"><strong>${j.reviewLevel==='automated-discovery'?'Automated discovery — qualifications not individually reviewed.':'Curated source review.'}</strong> ${e(j.reviewNote)}</p></div><div class="detail-bottom"><button class="button" data-detail-compare="${e(j.id)}">${state.compare.includes(j.id)?'Remove from comparison':'Add to comparison'}</button><a class="button primary" href="${safeUrl(j.applyUrl||j.url)}" target="_blank" rel="noopener noreferrer">Apply on official site ↗</a></div>`;
 if(show&&!$('#job-dialog').open)$('#job-dialog').showModal();
}
function exportCSV(){const blob=new Blob([toCSV(filtered())],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ai-career-compass-filtered-${state.meta.snapshotDate||'snapshot'}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Exported ${filtered().length} postings with source links.`);}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button,a');if(!b)return;
 if(b.dataset.view){ev.preventDefault();setView(b.dataset.view);}
 if(b.dataset.detail)openDetail(b.dataset.detail);
 if(b.dataset.save)toggleSave(b.dataset.save);
 if(b.dataset.compareRemove)toggleCompare(b.dataset.compareRemove);
 if(b.dataset.detailCompare){toggleCompare(b.dataset.detailCompare);openDetail(b.dataset.detailCompare,false);}
 if(b.dataset.clear){const k=b.dataset.clear;const f=state.filters;setFilter(k,Array.isArray(f[k])?f[k].filter(v=>v!==b.dataset.value):k==='includeUnknown'?true:typeof f[k]==='boolean'?false:'');}
 if(b.dataset.page){state.page=Number(b.dataset.page);render();$('#main').scrollIntoView({behavior:'smooth',block:'start'});}
 if(b.dataset.chart){let k=b.dataset.chart,v=b.dataset.value;if(k==='state'&&v==='Remote — US')v='Remote';setFilter(k,['degrees','roles'].includes(k)?[v]:v);setView('explore');}
 if(b.dataset.recommendRole){reset();state.filters.degrees=['Master'];state.filters.roles=[b.dataset.recommendRole];renderFilters();setView('explore');}
 const action=b.dataset.action;if(action==='reset')reset();if(action==='explore')setView('explore');if(action==='saved')setFilter('savedOnly',!state.filters.savedOnly);if(action==='clear-compare'){state.compare=[];render();}if(action==='close-detail')$('#job-dialog').close();if(action==='all-insights'){reset();setView('insights');}
 if(b.id==='reset')reset();if(b.id==='mobile-filters'){$('#filters').classList.add('open');$('#close-filters').focus();}if(b.id==='close-filters')$('#filters').classList.remove('open');if(b.id==='export')exportCSV();if(b.id==='share'){try{await navigator.clipboard.writeText(location.href);toast('Link copied. It includes these filters.');}catch{toast('Copy the page URL to share these filters.');}}
});
document.addEventListener('change',ev=>{const el=ev.target;if(el.dataset.array){const k=el.dataset.array;setFilter(k,el.checked?unique([...state.filters[k],el.value]):state.filters[k].filter(v=>v!==el.value));}if(el.dataset.filter)setFilter(el.dataset.filter,el.value);if(el.dataset.boolean)setFilter(el.dataset.boolean,el.checked);if(el.dataset.compare)toggleCompare(el.dataset.compare);if(el.id==='sort')setFilter('sort',el.value);});
let searchTimer;$('#search').addEventListener('input',ev=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.filters.q=ev.target.value;state.page=1;render();},160);});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')$('#filters').classList.remove('open');});
$('#job-dialog').addEventListener('click',ev=>{if(ev.target===$('#job-dialog')){const r=$('#job-dialog').getBoundingClientRect();if(ev.clientX<r.left)$('#job-dialog').close();}});
window.addEventListener('popstate',()=>{state.filters=filtersFromSearch(location.search);state.view=['guide','explore','insights','compare','methodology'].includes(location.hash.slice(1))?location.hash.slice(1):'guide';renderFilters();render();});
function setupWebMCP(){if(!document.modelContext?.registerTool)return;const controller=new AbortController();const tools=[{name:'search_ai_graduate_jobs',title:'Search US AI graduate roles',description:'Read jobs in the curated graduate sample with optional keyword, degree, state and role filters. Does not change the page.',inputSchema:{type:'object',properties:{keyword:{type:'string'},degree:{type:'string',enum:DEGREES},state:{type:'string'},role:{type:'string',enum:ROLE_FAMILIES}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['keyword','degree','state','role'].includes(k)))throw Error('Invalid search fields.');for(const v of Object.values(input))if(typeof v!=='string')throw Error('Search fields must be strings.');if(input.degree&&!DEGREES.includes(input.degree))throw Error('Invalid degree.');if(input.role&&!ROLE_FAMILIES.includes(input.role))throw Error('Invalid role.');const f=freshFilters();f.q=input.keyword||'';f.degrees=input.degree?[input.degree]:[];f.state=input.state||'';f.roles=input.role?[input.role]:[];const jobs=filteredJobs(state.jobs,f);return {count:jobs.length,jobs:jobs.slice(0,30).map(j=>({id:j.id,company:j.company,title:j.title,url:j.url}))};}},{name:'show_job_comparison',title:'Compare selected roles',description:'Show up to three collected roles in the visible comparison view.',inputSchema:{type:'object',properties:{jobIds:{type:'array',items:{type:'string'},minItems:1,maxItems:3,uniqueItems:true}},required:['jobIds'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).some(k=>k!=='jobIds')||!Array.isArray(input.jobIds)||input.jobIds.length<1||input.jobIds.length>3||new Set(input.jobIds).size!==input.jobIds.length||input.jobIds.some(id=>!state.jobs.some(j=>j.id===id)))throw Error('Provide one to three distinct valid job IDs.');state.compare=[...input.jobIds];setView('compare');return {view:state.view,comparedJobIds:[...state.compare]};}}];for(const tool of tools)Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
async function init(){try{const response=await fetch('./data.json');if(!response.ok)throw Error('Dataset could not be loaded.');const data=await response.json();state.jobs=data.jobs;state.meta=data.meta;state.coverage=data.coverage;state.saved=state.saved.filter(id=>state.jobs.some(j=>j.id===id));$('#snapshot-date').textContent=`Snapshot · ${date(state.meta.snapshotDate)}`;renderFilters();render();setupWebMCP();}catch(err){$('#view-content').innerHTML=`<div class="error-message"><h3>The snapshot could not be loaded.</h3><p>${e(err.message)}</p><p><a href="./downloads/jobs.csv">Download the dataset</a> or reload this page.</p></div>`;}}
init();
